WARRIOR = {
start = {"Battle Stance","Heroic Strike"},
about = {"Roles: damage (Arms, Fury) and tank (Protection). No healing.","Runs on Rage: you build it by hitting and being hit, and it drains away between fights.","Three stances: Battle (Charge, Overpower), Defensive at 10 (Taunt, Revenge), Berserker at 30 (Intercept, Whirlwind). Changing stance throws away most of your Rage.","Gear-hungry and slow to level alone: a good slow two-hander matters more than anything else."},
