PALADIN = {
start = {"Holy Light","Sense Undead"},
about = {"Roles: damage (Retribution), tank (Protection) and healer (Holy). Horde paladins are Undead in Forever.","Runs on Mana. Put a Seal on yourself, then Judgement releases it on the enemy.","Very hard to kill: heals, shields and bubbles. Slow but safe leveling, and welcome in any group.","Mail from the start, plate at 40. Two-handers for Retribution, sword or mace and shield for the rest."},
