multi={{"Consecration","Always under the pack: your group threat."},{"Holy Shield","Every block hurts them."},{"Retribution Aura","More threat from every hit you take."},{"Judgement","Taunts the one that runs to someone else."},{"","Bubbles drop you off the enemies' list: warn the healer first."}},
},
{role="heal",name="Healer (Holy)",plan="paladin-holy",l1="Tank healing",l2="Group healing",
single={{"Seal of Wisdom","Judge it on the boss and keep it there: Mana for everyone hitting it."},{"Flash of Light","Your everyday heal: cheap."},{"Holy Light","For big hits; start it early. Free to spend when Infusion of Light lights up."},{"Holy Shock","Instant: emergencies and while moving."},{"Divine Favor","With a big Holy Light."},{"Lay on Hands","Last resort: takes all your Mana."},{"Blessing of Protection","On a squishy friend being hit (not the tank)."}},
