MAGE = {
start = {"Fireball","Frost Armor"},
about = {"Role: damage only, from range, with the best area damage and crowd control.","Runs on Mana. Cloth. Makes its own food and water, and portals.","Fragile: slow them, freeze them, keep your distance.","Frost is the safe way to level; Fire and Arcane hit harder in groups."},
rot = {
{role="solo",name="Solo and leveling (Frost)",plan="mage-frost",l1="One enemy",l2="Several enemies",
single={{"Arcane Intellect/Frost Armor","Keep both up (Ice Armor later)."},{"Frostbolt","From as far as you can, and keep casting."},{"Ice Lance","When it's frozen, right as your Frostbolt leaves; also to spend Fingers of Frost."},{"Frost Nova","When it reaches you: step back, Frostbolt, Ice Lance."},{"Cone of Cold","Slow it, or at 5 stacks of Winter's Chill."},{"Fire Blast","To finish."},{"","Wand it when it's nearly dead: your Mana starts coming back."},{"Ice Barrier","Before a hard fight."},{"Polymorph","The second enemy."},{"Counterspell","Casters."}},
multi={{"Frost Nova","Freeze them, then..."},{"Cone of Cold","...into the frozen pack; again when it's ready or Fingers of Frost lights up."},{"Blizzard","From a distance, on slowed packs."},{"Arcane Explosion","When they can't hurt you much."},{"Ice Block/Cold Snap","Trouble."}},
},
{role="dps",name="Dungeon and raid damage (Fire)",plan="mage-fire-raid",l1="One enemy",l2="Several enemies",
single={{"Pyroblast","Cast it as the tank pulls."},{"Scorch","Until Improved Scorch is at 5, then just to keep it up."},{"Fireball","Your main spell."},{"Fire Blast","On cooldown."},{"Pyroblast","Every time Heating Up reaches 3."},{"Arcane Missiles","When Missile Barrage lights up."},{"Combustion","Burst."},{"Counterspell","Interrupts."},{"Evocation","Mana."}},
multi={{"Flamestrike","First; again when it runs out (it doesn't stack)."},{"Blast Wave","On cooldown if you have it."},{"Arcane Explosion","Then this, as long as the tank holds them."},{"Blizzard","If it's not safe to go near."},{"Polymorph","Take one out before the pull."}},
},
},
macros = {
{"Sheep your focus","Keep one enemy as your focus and re-sheep it without changing target.","#showtooltip Polymorph\n/cast [@focus,harm,nodead][] Polymorph"},
{"Counterspell now","Drops your own cast first.","#showtooltip Counterspell\n/stopcasting\n/cast [@focus,harm,nodead][] Counterspell"},
{"Ice Block on and off","Press again to leave it early.","#showtooltip Ice Block\n/cancelaura Ice Block\n/stopcasting\n/cast Ice Block"},
{"Wand without stopping","","#showtooltip Shoot\n/cast !Shoot"},
{"Food or water","Shift for water.","#showtooltip\n/cast [mod:shift] Conjure Water; Conjure Food"},
{"Curse off a friend","","#showtooltip Remove Lesser Curse\n/cast [@mouseover,help,nodead][help,nodead][@player] Remove Lesser Curse"},
},
openers = {
{"pull","Frost pull","Frostbolts on the way in, Fire Blast when it arrives.","target/12",{"Frostbolt","Frostbolt","Frostbolt","Fire Blast"},{},{},""},
{"pull","Fire pull","Pyroblast, Scorch or Fireball, then Fire Blast.","target/12",{"Pyroblast|Fireball","Scorch|Fireball","Fireball","Fire Blast"},{},{},""},
{"pull","Get away","Roots them, then Blink: turn the way you want to go first.","12",{"Frost Nova","Blink"},{},{},""},
{"pull","Several at once","Roots, then cone, then explosion.","12",{"Frost Nova","Cone of Cold","Arcane Explosion"},{},{},""},
{"prep","Buff up","Intellect and your armor spell.","30",{"Arcane Intellect","Ice Armor|Frost Armor"},{},{},"[@player] "},
{"prep","Food and water","Water, then food.","30",{"Conjure Water","Conjure Food"},{},{},""},
} },
WARLOCK = {
start = {"Demon Skin","Shadow Bolt"},
about = {"Role: damage, from range, with a demon to fight for you. The Voidwalker tanks while you solo.","Runs on Mana and Health: Life Tap turns health into Mana, Drain Life turns it back.","Damage over time, fear, and Soul Shards (from Drain Soul) for pets and Healthstones. Cloth.","Great solo, even against elites, if you let the demon hold them."},
rot = {
{role="solo",name="Solo, elites and dungeons (Demonology)",plan="warlock-solo",l1="One enemy",l2="Several enemies",
single={{"Summon Voidwalker","Send it first and let it get a hit in."},{"Searing Pain","From 25: puts Demonic Brand on its target, so its next attacks hit harder. Redo it when used up."},{"Bane of Agony","If it will live through most of it."},{"Corruption","Same."},{"Immolate","On tough ones."},{"","Wand to finish, and let the demon do its work."},{"Drain Life","When you're hurt."},{"Health Funnel","When the demon is."},{"Life Tap","Instead of drinking (it also feeds the demon with Demonic Energies)."},{"Drain Soul","Last seconds: a Soul Shard."}},
multi={{"Corruption/Bane of Agony","On each one, while the demon holds the toughest."},{"Searing Pain","Brand the one the demon is on, and swap it around to spread its threat."},{"Fear","One of them."},{"Rain of Fire","On a pack your demon is holding."},{"Hellfire","From 30, with healing: it hurts you too."},{"Howl of Terror/Death Coil","Trouble."}},
},
{role="solo",name="Fast leveling (Affliction)",plan="warlock-leveling",l1="One enemy",l2="Several enemies",
single={{"Corruption","First; instant with Improved Corruption."},{"Bane of Agony","Let it run out before you redo it."},{"Siphon Life","On long fights."},{"Shadow Bolt","When Nightfall makes it instant."},{"Drain Life","When hurt; after Life Tap."},{"","Wand the rest."},{"Life Tap","When your health is higher than your Mana."},{"Drain Soul","To finish: a Shard."}},
multi={{"Corruption/Bane of Agony","Put both on everything, one after another."},{"Drain Life","Then drain while they tick."},{"Fear","Keep one running."},{"Rain of Fire/Hellfire","Only in groups."}},
},
{role="dps",name="Dungeon and raid damage (Demonology)",plan="warlock-demonology-raid",l1="One enemy",l2="Several enemies",
single={{"Soul Fire","Cast as the tank pulls; send your demon to land with it."},{"Searing Pain","Whenever Demonic Brand is missing."},{"Bane of Doom","If a minute or more is left; else Bane of Agony."},{"Curse of the Elements","Or the curse your raid asks for."},{"Immolate","Keep it up."},{"Soul Fire","While Decimation is active (Fire build)."},{"Corruption","Keep it up."},{"Life Tap","In the gaps, or moving."},{"Shadow Bolt","Filler (Searing Pain in the Fire build)."}},
multi={{"Curse of the Elements","On the main target."},{"Bane of Agony","On every enemy as they run in."},{"Hellfire","Three or more, once the tank has them."},{"Rain of Fire","If it isn't safe to stand close."},{"","Don't put slow damage on things about to die."}},
},
},
macros = {
{"Send the demon and curse","","#showtooltip Corruption\n/petattack\n/cast Corruption"},
{"Two enemies, one button","Shift puts it on your focus.","#showtooltip Corruption\n/cast [mod:shift,@focus,harm,nodead] Corruption; Corruption"},
{"Fear your focus","","#showtooltip Fear\n/cast [@focus,harm,nodead][] Fear"},
{"Stronger Agony","Amplify Curse first, when it's ready.","#showtooltip Bane of Agony\n/cast Amplify Curse\n/cast Bane of Agony"},
{"Wand without stopping","","#showtooltip Shoot\n/cast !Shoot"},
{"Drain without clipping","Pressing early doesn't restart it.","#showtooltip Drain Life\n/cast [nochanneling] Drain Life"},
{"Demon, come back","","/petpassive\n/petfollow"},
},
openers = {
{"pull","Send the demon, then curses","Sends your demon on every press and goes through your damage over time. With a Voidwalker, press once and give it a moment.","target/12",{"Bane of Agony","Corruption","Immolate","Siphon Life"},{{"","/petattack"}},{},""},
{"pull","Quick kill","For what dies before the curses finish.","target/12",{"Immolate","Corruption","Shadow Bolt","Shadowburn|Shadow Bolt"},{{"","/petattack"}},{},""},
{"pull","Get away","Fear it, then curse it while it runs.","target/15",{"Fear","Bane of Agony","Corruption"},{},{},""},
{"prep","Armor up","Your demon armor, and Soul Link if you have it.","20",{"Demon Armor|Demon Skin","Soul Link"},{},{},""},
{"prep","Stones","Healthstone; hold Alt for a Soulstone.","",{},{{"Create Soulstone","/cast [mod:alt] Create Soulstone"},{"Create Healthstone","/cast [nomod:alt] Create Healthstone"}},{},""},
} },
DRUID = {
start = {"Healing Touch","Wrath"},
about = {"Roles: tank (Bear), damage (Cat, or Balance from range) and healer (Restoration). The only class that does all of it.","Each form has its own resource: Bear uses Rage, Cat uses Energy, the rest Mana.","Bear at 10 (class quest), Aquatic 16, Cat 20, Travel 30. Cat can Prowl like a rogue.","Leather. Forms ignore your weapon's damage: look at stats."},
rot = {
{role="solo",name="Solo and leveling (Cat)",plan="druid-feral",l1="One enemy",l2="Several enemies",
single={{"Mark of the Wild/Thorns","Keep both up."},{"Prowl","Open from it: Ravage, or Shred from behind."},{"Rake","If it will live 9 seconds."},{"Shred","From behind; Claw from the front."},{"Rip","4 or 5 points, if it lives long enough."},{"Ferocious Bite","Otherwise."},{"Shifting Power","Below half Energy, on cooldown."},{"Rejuvenation/Healing Touch","Between fights."},{"Wrath/Moonfire","Before 20, with Bear Form for tough ones."}},
multi={{"Bear Form","Tougher, and it hits several."},{"Demoralizing Roar","First."},{"Swipe","Then this."},{"Thorns","Hurts them all."},{"Barkskin/Frenzied Regeneration","Trouble."}},
},
{role="tank",name="Tank (Bear)",plan="druid-bear",l1="One enemy",l2="Several enemies",
single={{"Thorns/Mark of the Wild","Keep both up."},{"Faerie Fire","Pull with it."},{"Enrage","Just before the pull for Rage."},{"Demoralizing Roar","Keep it up."},{"Primal Bite","On cooldown."},{"Lacerate","Build to 5, keep it there."},{"Maul","Extra Rage."},{"Growl","Taunt, when someone else has it."},{"Barkskin/Frenzied Regeneration","Emergencies."}},
multi={{"Demoralizing Roar","First."},{"Swipe","Over and over."},{"Primal Bite","On the main one."},{"Challenging Roar","When several get loose."},{"Growl","One loose enemy."}},
},
{role="dps",name="Dungeon and raid damage (Cat)",plan="druid-cat-raid",l1="One enemy",l2="Several enemies",
single={{"Faerie Fire","Keep it up."},{"Rake","Put it back when it falls off, not before."},{"Rip","At 5 points."},{"Ferocious Bite","4 or 5 points with 70 Energy, when Rip is up."},{"Shred","From behind: your builder (Claw if you can't)."},{"Shifting Power","Below half Energy, on cooldown."},{"Cower","If you draw attention."}},
multi={{"Rake","On several."},{"","Cat has no area damage: kill one at a time, or Swipe in Bear Form on big packs."}},
},
{role="heal",name="Healer (Restoration)",plan="druid-restoration",l1="Tank healing",l2="Group healing",
single={{"Rejuvenation","Keep it on the tank."},{"Regrowth","When it's dropping and has none."},{"Swiftmend","Instant, uses up one of those."},{"Healing Touch","The size you need for what's left."},{"Nature's Swiftness","Then an instant Healing Touch: emergencies."},{"Innervate","Mana, for you or another healer."},{"Remove Curse/Abolish Poison","Off friends."},{"Rebirth","Brings someone back in combat."}},
multi={{"Wild Growth","Several in one party."},{"Rejuvenation","On everyone being hit."},{"Swiftmend","The lowest one that has a heal over time."},{"Regrowth","Bigger hits."},{"Tranquility","Stand still; whole party."}},
},
},
